const score75=[[0,18,100,295,'Inicial'],[19,32,309,474,'Basico'],[33,47,489,657,'Intermedio'],[48,61,672,827,'Alto'],[62,75,843,1000,'Avanzado']];
function historyQ(n){
 const t=(n-1)%12;
 const diff=n%5===0?'Dificil':n%2===0?'Media':'Facil';
 const qs=[
 ['Historia: Chile siglo XIX','¿Que proceso contribuyo directamente a la consolidacion del Estado chileno durante el siglo XIX?','La organizacion de instituciones republicanas y un orden constitucional',['La desaparicion de toda autoridad central','La eliminacion inmediata de las fronteras','La sustitucion de elecciones por herencia monarquica'],'La consolidacion estatal se vinculo a la construccion de instituciones, marcos constitucionales y administracion publica.'],
 ['Historia: Chile siglo XX','Una consecuencia social relevante de la urbanizacion chilena durante el siglo XX fue:','El crecimiento de ciudades y nuevas demandas de vivienda y servicios',['La desaparicion de la migracion interna','El retorno masivo a una economia exclusivamente rural','La eliminacion de las diferencias territoriales'],'La urbanizacion incremento la poblacion urbana y genero presiones sobre vivienda, transporte y servicios.'],
 ['Historia mundial','¿Que caracterizo a la Revolucion Industrial?','La mecanizacion productiva y el crecimiento del trabajo fabril',['El abandono general de las maquinas','La desaparicion del comercio','La eliminacion de la division del trabajo'],'La Revolucion Industrial transformo produccion, energia, transporte y relaciones laborales mediante mecanizacion y fabrica.'],
 ['Historia mundial','Tras la Segunda Guerra Mundial, una caracteristica del orden internacional fue:','La rivalidad entre Estados Unidos y la Union Sovietica',['La inexistencia de organismos internacionales','La desaparicion de conflictos ideologicos','La unificacion politica inmediata del planeta'],'La Guerra Fria organizo gran parte de las relaciones internacionales en torno a dos grandes bloques.'],
 ['Formacion ciudadana','En una democracia representativa, la separacion de poderes busca principalmente:','Evitar la concentracion del poder y establecer controles reciprocos',['Eliminar la funcion de los tribunales','Impedir toda participacion ciudadana','Concentrar todas las decisiones en una sola autoridad'],'La separacion de poderes crea contrapesos institucionales y limita la concentracion de autoridad.'],
 ['Formacion ciudadana','¿Cual de las siguientes acciones fortalece la participacion ciudadana informada?','Contrastar fuentes antes de formar una opinion publica',['Compartir informacion sin verificar','Excluir opiniones distintas por principio','Evitar toda deliberacion colectiva'],'La ciudadania informada requiere evaluar evidencia, fuentes y argumentos antes de decidir o participar.'],
 ['Economia y sociedad','Si el precio de un bien aumenta y, manteniendo lo demas constante, disminuye la cantidad demandada, se observa:','La relacion inversa descrita por la ley de demanda',['Una eliminacion del mercado','Un aumento automatico de la oferta monetaria','Una relacion sin vinculo entre precio y cantidad'],'La ley de demanda describe una relacion inversa entre precio y cantidad demandada, ceteris paribus.'],
 ['Economia y sociedad','¿Que indicador se usa habitualmente para medir la variacion general de precios de bienes y servicios de consumo?','El indice de precios al consumidor',['La tasa de alfabetizacion','La longitud de la red vial','La cantidad de comunas'],'El IPC resume cambios de precios de una canasta representativa y se utiliza para aproximar inflacion.'],
 ['Territorio y ambiente','¿Que informacion permite obtener principalmente un mapa de densidad de poblacion?','La concentracion relativa de habitantes por unidad de superficie',['La edad exacta de cada habitante','El ingreso individual de toda persona','La opinion politica de cada comuna'],'La densidad relaciona poblacion y superficie y permite comparar concentraciones territoriales.'],
 ['Territorio y ambiente','Una politica de gestion de riesgo frente a tsunamis deberia priorizar:','Rutas de evacuacion, educacion y sistemas de alerta',['Construir solo en zonas de inundacion','Eliminar toda señalizacion preventiva','Depender exclusivamente de reaccion posterior'],'La reduccion del riesgo combina prevencion, informacion, infraestructura y preparacion comunitaria.'],
 ['Analisis de fuentes','Un historiador compara una carta privada con un decreto oficial del mismo periodo. ¿Para que sirve principalmente este contraste?','Para reconocer perspectivas y propositos diferentes de las fuentes',['Para asumir que ambas fuentes son identicas','Para eliminar la necesidad de contextualizar','Para probar que toda fuente privada es falsa'],'Contrastar fuentes permite evaluar autoria, proposito, contexto y posibles sesgos.'],
 ['Analisis de fuentes','Si una tabla muestra que un indicador aumenta de forma sostenida durante diez anos, ¿que conclusion es mas rigurosa?','Existe una tendencia ascendente en el periodo observado',['El indicador aumentara necesariamente para siempre','La causa del aumento queda demostrada por la tabla','Todos los territorios tuvieron exactamente el mismo comportamiento'],'Una serie temporal permite describir tendencia, pero no prueba por si sola causalidad ni permite extrapolar sin limites.']
 ];
 const [skill,text,correct,wrong,ex]=qs[t]; return mk(n,text,correct,wrong,skill,diff,ex,n<=60);
}
function scienceBaseQ(n,module){
 const common=[
 ['Biologia - Organizacion celular','¿Que estructura celular participa directamente en la sintesis de proteinas?','Los ribosomas',['Los lisosomas','El centriolo como unica estructura','La pared celular'],'Los ribosomas traducen ARN mensajero y ensamblan aminoacidos para formar proteinas.'],
 ['Biologia - Procesos biologicos','Durante la fotosintesis, la energia luminica se transforma principalmente en:','Energia quimica almacenada en moleculas organicas',['Energia nuclear','Masa sin energia','Solo energia mecanica'],'La fotosintesis convierte energia luminica en energia quimica utilizable por los organismos.'],
 ['Fisica - Ondas','Si aumenta la frecuencia de una onda y su rapidez en el medio permanece constante, su longitud de onda:','Disminuye',['Aumenta necesariamente','Permanece infinita','Se vuelve independiente de la frecuencia'],'Como v=f lambda, con rapidez constante, mayor frecuencia implica menor longitud de onda.'],
 ['Fisica - Mecanica','Un cuerpo se mueve con velocidad constante en linea recta. La fuerza neta sobre el cuerpo es:','Cero',['Necesariamente positiva','Igual a su masa','Siempre vertical'],'Segun la primera ley de Newton, velocidad constante implica aceleracion nula y fuerza neta cero.'],
 ['Quimica - Estructura atomica','El numero atomico de un elemento corresponde al numero de:','Protones del nucleo',['Neutrones mas electrones siempre','Orbitales ocupados','Enlaces covalentes'],'El numero atomico Z identifica al elemento y corresponde a la cantidad de protones.'],
 ['Quimica - Reacciones','En una reaccion quimica balanceada se cumple que:','Se conserva el numero de atomos de cada elemento',['Desaparece parte de la materia','Siempre aumenta el numero total de moleculas','Los productos no contienen los mismos elementos'],'El balanceo representa la conservacion de la materia mediante igual numero de atomos por elemento.'],
 ['Habilidades cientificas','Un experimento cambia solo la temperatura y mide la rapidez de reaccion. La temperatura es:','La variable independiente',['La variable dependiente','Una conclusion','El grupo control'],'La variable independiente es el factor manipulado deliberadamente por quien investiga.'],
 ['Habilidades cientificas','Una investigacion obtiene resultados distintos a la hipotesis inicial. ¿Que corresponde hacer?','Analizar la evidencia y revisar la explicacion propuesta',['Modificar los datos para que coincidan','Descartar siempre el experimento','Mantener la hipotesis sin considerar resultados'],'Las hipotesis se contrastan con evidencia y deben revisarse cuando los datos no las apoyan.']
 ];
 const elect={
 fisica:[
 ['Fisica electiva - Electricidad','Dos resistencias identicas se conectan en serie. La resistencia equivalente es:','La suma de ambas resistencias',['La mitad de una resistencia','Cero en todos los casos','Igual al voltaje de la fuente'],'En serie, las resistencias se suman.'],
 ['Fisica electiva - Energia','Al caer un objeto sin roce, la energia potencial gravitatoria disminuye mientras la energia cinetica:','Aumenta',['Desaparece','Permanece siempre cero','Se transforma solo en masa'],'Sin roce, la energia mecanica se conserva y la disminucion de potencial se convierte en cinetica.'],
 ['Fisica electiva - Ondas','La refraccion ocurre cuando una onda:','Cambia su rapidez al pasar a otro medio',['Se destruye al reflejarse','Pierde toda frecuencia','Solo se mueve en el vacio'],'Al cambiar de medio puede cambiar rapidez y direccion, manteniendose la frecuencia determinada por la fuente.'],
 ['Fisica electiva - Mecanica','Si una fuerza neta constante actua sobre una masa, segun la segunda ley de Newton la aceleracion es:','Directamente proporcional a la fuerza neta',['Independiente de la fuerza','Siempre cero','Igual a la energia potencial'],'F=ma, por lo que para masa fija la aceleracion aumenta con la fuerza neta.']
 ],
 quimica:[
 ['Quimica electiva - Estequiometria','Si una ecuacion indica 2 mol de H2 por 1 mol de O2, ¿cuantos mol de O2 se requieren para 4 mol de H2?','2 mol',['1 mol','4 mol','8 mol'],'La proporcion estequiometrica 2:1 implica que 4 mol de H2 requieren 2 mol de O2.'],
 ['Quimica electiva - Organica','¿Que grupo funcional caracteriza a los alcoholes?','El grupo hidroxilo -OH',['El grupo amino como unica opcion','Solo enlaces ionicos','El neutron'],'Los alcoholes contienen un grupo hidroxilo unido a un carbono.'],
 ['Quimica electiva - Soluciones','Si se agrega solvente a una solucion sin cambiar la cantidad de soluto, la concentracion:','Disminuye',['Aumenta siempre','No puede cambiar','Se vuelve negativa'],'Al aumentar el volumen con igual cantidad de soluto se produce dilucion y disminuye la concentracion.'],
 ['Quimica electiva - Reacciones','Un catalizador aumenta la rapidez de reaccion porque:','Ofrece una ruta con menor energia de activacion',['Aumenta la masa total','Cambia los productos finales necesariamente','Se consume por completo en toda reaccion'],'El catalizador disminuye la energia de activacion sin alterar la estequiometria global.']
 ],
 tp:[
 ['Ciencias TP - Seguridad','Antes de manipular una sustancia desconocida en un laboratorio o taller, la accion mas adecuada es:','Revisar su ficha de seguridad y usar proteccion apropiada',['Olerla directamente','Mezclarla con otras sustancias','Calentarla sin informacion previa'],'La gestion segura exige identificar peligros, medidas preventivas y elementos de proteccion.'],
 ['Ciencias TP - Medicion','Para mejorar la confiabilidad de una medicion repetida conviene:','Realizar varias mediciones y analizar su dispersion',['Conservar solo el valor mas alto','Cambiar de unidad en cada intento','Evitar registrar incertidumbre'],'La repeticion y el analisis de variabilidad permiten estimar precision y detectar valores atipicos.'],
 ['Ciencias TP - Electricidad aplicada','Un fusible protege un circuito porque:','Interrumpe la corriente cuando esta supera un valor seguro',['Aumenta indefinidamente el voltaje','Almacena combustible','Elimina la resistencia de todos los componentes'],'El fusible se abre ante sobrecorriente y reduce riesgo de dano o incendio.'],
 ['Ciencias TP - Ambiente','En un proceso productivo, separar residuos peligrosos de residuos comunes permite principalmente:','Reducir riesgos y gestionar cada residuo segun sus propiedades',['Aumentar la mezcla de contaminantes','Evitar todo registro','Eliminar la necesidad de tratamiento'],'La segregacion facilita manejo seguro, trazabilidad y disposicion adecuada.']
 ]};
 const diff=n%5===0?'Dificil':n%2===0?'Media':'Facil';
 let row;
 if(n<=54) row=common[(n-1)%common.length]; else row=(elect[module]||elect.fisica)[(n-55)%4];
 const [skill,text,correct,wrong,ex]=row; return mk(n,text,correct,wrong,skill,diff,ex,n<=75);
}
